    WHERE attrelid = format('public.%I', target)::regclass AND attnum > 0 AND NOT attisdropped;

    EXECUTE format('DELETE FROM public.%I WHERE content_version = %L', target, 'v4');
    EXECUTE format(
      'INSERT INTO public.%I (%s) SELECT %s FROM public.%I WHERE content_version = %L',
      target, column_list, projection, target, 'v3');

    EXECUTE format('SELECT count(*) FROM public.%I WHERE content_version = %L', target, 'v4') INTO copied;
    EXECUTE format('SELECT count(*) FROM public.%I WHERE content_version = %L', target, 'v3') INTO expected;
    IF copied <> expected OR expected = 0 THEN
      RAISE EXCEPTION 'V4 copy of % is incomplete (% of %)', target, copied, expected;
    END IF;
  END LOOP;
END
